const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
fs.mkdirSync(STATE, { recursive: true });
const token = ENV('TELEGRAM_BOT_TOKEN');
// Every secret this run hands to httpRequest lands in SECRET_VALUES:
// an error object from helpers.httpRequest can carry the request
// config (body.secret_token on setWebhook, the bot token inside the
// URL, any X-*-Secret headers) into n8n execution history, where it
// persists in plain text. tg() therefore rethrows a CLEAN Error -
// message scrubbed of every known secret, no response/request config
// attached - instead of propagating the raw error object. Same
// masking discipline as scrub()/KNOWN_TOKENS in sp-publish and
// scrubSecrets in sp-tg-moderation (Handle TG Update) /
// sp-content-gen; the >=8 length floor avoids shredding unrelated
// message text.
const SECRET_VALUES = [];
if (token) SECRET_VALUES.push(token);
const scrubSecrets = (s) => {
  let out = String(s);
  for (const v of SECRET_VALUES) {
    if (v && v.length >= 8) out = out.split(v).join('***');
  }
  return out;
};
const tg = async (method, body) => {
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + token + '/' + method,
      body: body || {},
      json: true,
      // explicit 30s timeout, same as the tg() helpers in
      // sp-tg-moderation / sp-publish: helpers.httpRequest is
      // unbounded by default, so a hung api.telegram.org socket
      // would stall this manual setup run forever
      timeout: 30000
    });
  } catch (e) {
    // strip, don't rethrow: n8n keeps a failed node's error object in
    // execution data, and the raw httpRequest error may embed the
    // request config with secret_token in the body. The clean error
    // carries only a scrubbed message.
    throw new Error('tg ' + method + ' request failed: ' +
      scrubSecrets(e && (e.description || e.message) || e).slice(0, 300));
  }
};
// atomic state write: tmp + rename - a crash mid-writeFileSync would
// leave a torn tg.json behind, and every moderation reader treats it
// as the pinned-chat fallback. Same discipline as the sibling
// writeJsonAtomic copies in sp-tg-moderation (Handle TG Update,
// Prepare Draft, Compose Message), sp-publish (hardened 0o600
// variant) and sp-content-gen.
// SYNC: n8n Code nodes cannot share a prelude - replicate any fix
// to every copy by hand.
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};

// Fail fast on a missing webhook secret: registering with
// secret_token=undefined leaves every delivery UNSIGNED while Handle
// TG Update fails closed on a missing signature - moderation goes
// silently dead while this node reports 'webhook registered'. Same
// guard as tools/tg_webhook_setup.sh's `:?` check. The env is passed
// through docker-compose.yml from ../ENV.
const hookSecret = ENV('TG_WEBHOOK_SECRET');
if (hookSecret) SECRET_VALUES.push(hookSecret);
if (!hookSecret) {
  throw new Error('TG_WEBHOOK_SECRET is not set - refusing to register ' +
    'an unsigned webhook (the tg-moderation gate would drop every ' +
    'update). Generate one (openssl rand -hex 32), add it to ../ENV, ' +
    'recreate the n8n container, then re-run this workflow.');
}
// same fail-fast for the public base URL: an unset WEBHOOK_URL would
// register '/webhook/tg-moderation' - a relative URL Telegram rejects
// with a far less actionable error than this upfront check
const webhookBase = ENV('WEBHOOK_URL');
if (!webhookBase) {
  throw new Error('WEBHOOK_URL is not set - cannot register the ' +
    'tg-moderation webhook. Add the public n8n base URL (e.g. ' +
    'https://<edge-host>:<port>/) to ../ENV, recreate the n8n ' +
    'container, then re-run this workflow.');
}

// 1. resolve the operator chat_id. PINNED config wins over discovery:
// TELEGRAM_CHAT_ID env first, then the tg.json written by a previous
// run. The getUpdates self-heal runs only when neither exists AND no
// webhook is registered yet - and it pins whoever messaged the bot
// LAST, so a third party writing between the operator's /start and
// this run would become 'operator' (see the multi-chat warning below).
// sp-tg-moderation never learns chat_id from untrusted updates.
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
let chatSource = chatId ? 'TELEGRAM_CHAT_ID env' : null;
if (!chatId) {
  try {
    chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id;
    chatSource = chatId ? 'tg.json' : null;
  } catch (e) {}
}
const info = await tg('getWebhookInfo');
const hookAlreadySet = !!(info.result && info.result.url);
let updateChats = 0;
if (!chatId && !hookAlreadySet) {
  const r = await tg('getUpdates', { limit: 50 });
  const seen = {};
  let maxUpdateId = -1;
  for (const u of (r.result || [])) {
    if (u && u.update_id > maxUpdateId) maxUpdateId = u.update_id;
    const m = u.message || u.edited_message || (u.callback_query && u.callback_query.message);
    if (m && m.chat && m.chat.id) {
      seen[String(m.chat.id)] = true;
      chatId = m.chat.id;
    }
  }
  updateChats = Object.keys(seen).length;
  if (chatId) chatSource = 'getUpdates last sender';
  // confirm the consumed updates: getUpdates only DISCARDS a queued
  // update once a later call passes offset > its update_id, so without
  // this second call everything just read stays pending (up to 24h)
  // and replays on the next poll - or to the webhook the moment it
  // registers. Best-effort: setWebhook's drop_pending_updates below is
  // the primary flush, so a failed confirm must not fail the run.
  if (maxUpdateId >= 0) {
    try {
      await tg('getUpdates', { offset: maxUpdateId + 1, limit: 1 });
    } catch (e) {}
  }
}
if (chatId) {
  writeJsonAtomic(STATE + '/tg.json',
    { chat_id: chatId, saved_at: new Date().toISOString() });
}

// 2. point the bot webhook at the moderation callback endpoint.
// setWebhook does not depend on chatId - keep it OUT of the chat
// resolution branch and re-register on EVERY run: the call is
// idempotent, so it also heals a rotated TG_WEBHOOK_SECRET or a
// drifted url/allowed_updates on a bot whose chat was pinned long
// ago. Skipping it whenever the chat did not (re-)resolve would leave
// the old registration live while Handle TG Update verifies incoming
// signatures against the NEW secret and drops every delivery.
const base = webhookBase.replace(/\/+$/, '');
const hook = await tg('setWebhook', {
  url: base + '/webhook/tg-moderation',
  allowed_updates: ['message', 'callback_query'],
  // drop every update Telegram queued while no webhook was registered
  // (it keeps them up to 24h): without this the backlog replays to
  // tg-moderation the moment registration lands, and a stale 'ap:<id>'
  // callback or replayed 'post N' passes the signature gate and acts on
  // CURRENT state - a dead Approve can enqueue a real wall.post. Safe
  // here: the chat_id the getUpdates self-heal needs is already
  // captured above, so nothing depends on the dropped updates. Same
  // flag in tools/tg_webhook_setup.sh.
  drop_pending_updates: true,
  // authenticity: Telegram signs every delivery with this token
  // (X-Telegram-Bot-Api-Secret-Token header), which Handle TG
  // Update verifies before touching any update. The same
  // registration lives in tools/tg_webhook_setup.sh. Required -
  // the guard above aborts the run when the env is unset.
  secret_token: hookSecret
});

let note;
if (chatId && hook && hook.ok) {
  note = 'chat_id saved (' + chatSource + '), webhook registered with secret_token';
} else if (chatId && !(hook && hook.ok)) {
  // the chat resolved fine but setWebhook did not return ok - the
  // /start hint below would point the operator at the wrong fix (the
  // chat is already pinned); surface the webhook cause instead
  note = 'chat_id saved (' + chatSource + ') but setWebhook failed - ' +
    'check WEBHOOK_URL reachability and the Telegram error in this run output';
} else if (hook && hook.ok) {
  // webhook (re-)registered but no operator chat resolved: with a
  // live webhook Telegram stops answering getUpdates, so the chat
  // can only come from pinned config
  note = 'webhook registered with secret_token; no chat_id resolved - ' +
    'set TELEGRAM_CHAT_ID in ENV or restore ' + STATE + '/tg.json';
} else {
  note = 'setWebhook failed and no chat_id resolved - check ' +
    'WEBHOOK_URL reachability and the Telegram error in this run ' +
    'output, then send /start to @shared_person_bot and re-run';
}
// the getUpdates fallback pins whoever messaged the bot LAST - a
// third party between the operator's /start and this run becomes
// 'operator'. Warn loudly when several distinct chats wrote in so the
// operator verifies tg.json instead of trusting a hijack.
if (updateChats > 1) {
  note += ' | WARNING: getUpdates saw ' + updateChats + ' distinct ' +
    'chats - the LAST sender became tg.json. Verify it is yours, or ' +
    'pin TELEGRAM_CHAT_ID in ENV and re-run';
}
// 'ok' now means the whole setup job succeeded - a pinned chat with
// a failed setWebhook (or vice versa) is a half-configured bot, and
// the note above already says which half broke
return [{ json: { ok: !!(chatId && hook && hook.ok), chat_id: chatId, chat_source: chatSource, webhook_set: !!(hook && hook.ok), note: note } }];
